    48	    public static String typeName(fortress.AnyType.Any a) {
    49	        return fortressTypeName(Naming.demangleFortressIdentifier(Naming.dotToSep(a.getClass().getName())));
    50	    }
    51	
    52	    private static String fortressTypeName(String s) {
    53	        if (s.equals(Naming.SNOWMAN)) return "()";
    54	        int left = s.indexOf(Naming.LEFT_OXFORD_CHAR);
    55	        String stem = left == -1 ? s : s.substring(0, left);
    56	        String name = stem.substring(Math.max(stem.lastIndexOf('/'), stem.lastIndexOf('$')) + 1);
    57	        if (stem.startsWith(Naming.RT_VALUES_PKG)) name = name.substring(1); // FZZ32 is ZZ32
    58	        if (left == -1) return name;
    59	        List<String> args = RTHelpers.extractStringParameters(s);
    60	        boolean arrow = stem.equals(Naming.ARROW_TAG) || stem.equals(Naming.ABSTRACT_ARROW);
    61	        int last = arrow ? args.size() - 1 : args.size();
    62	        StringBuilder sb = new StringBuilder();
    63	        for (int i = 0; i < last; i++)
    64	            sb.append(i == 0 ? "" : ",").append(fortressTypeName(args.get(i)));
    65	        String inner = sb.toString();
    66	        if (arrow)
    67	            return (last == 1 ? inner : "(" + inner + ")") + "->" + fortressTypeName(args.get(last));
    68	        if (stem.equals(Naming.TUPLE_TAG) || stem.equals(Naming.CONCRETE_TUPLE))
    69	            return "(" + inner + ")";
    70	        return name + "[\\" + inner + "\\]";
    71	    }
    72	
    73	}
