     1	(* See explorations/compile-ladder/rung-default-rendering/REPORT.md. *)
     2	
     3	component DefaultRenderRungS
     4	export Executable
     5	
     6	object Box(n: ZZ32) end
     7	object Cell[\T\](v: T) end
     8	object Two[\A, B\](a: A, b: B) end
     9	object AnyCell[\T extends Any\](v: T) end
    10	object Tag[\T extends Any\]() end
    11	value object Pt(x: ZZ32) end
    12	object Boom extends UncheckedException end
    13	
    14	inc(x: ZZ32): ZZ32 = x + 1
    15	add(x: ZZ32, y: ZZ32): ZZ32 = x + y
    16	
    17	run(): () = do
    18	    println(Box(1))
    19	    println(Cell[\ZZ32\](1))
    20	    println(Pt(1))
    21	    assert(Box(1).asString, "Box", "plain object; ledger row 321, walk prints Box")
    22	    assert(Cell[\ZZ32\](1).asString, "Cell[\\ZZ32\\]", "generic object; ledger row 321, walk prints Cell[\\ZZ32\\]")
    23	    assert(Pt(1).asString, "Pt", "value object; ledger row 321, walk prints Pt")
    24	    assert(Two[\ZZ32, String\](1, "a").asString, "Two[\\ZZ32,String\\]", "two static arguments; ledger row 321")
    25	    assert(Cell[\Box\](Box(2)).asString, "Cell[\\Box\\]", "a user object as the argument; ledger row 321")
    26	    assert(Cell[\Cell[\ZZ32\]\](Cell[\ZZ32\](3)).asString, "Cell[\\Cell[\\ZZ32\\]\\]", "nested instance; ledger row 321")
    27	    assert(AnyCell[\(ZZ32, String)\]((1, "a")).asString, "AnyCell[\\(ZZ32,String)\\]", "tuple argument; ledger row 321, walk prints (A,B)")
    28	    assert(AnyCell[\ZZ32 -> ZZ32\](inc).asString, "AnyCell[\\ZZ32->ZZ32\\]", "arrow argument; ledger row 321, walk prints A->B")
    29	    assert(AnyCell[\(ZZ32, ZZ32) -> ZZ32\](add).asString, "AnyCell[\\(ZZ32,ZZ32)->ZZ32\\]", "arrow of two arguments; ledger row 321")
    30	    assert(Tag[\()\]().asString, "Tag[\\()\\]", "void argument; ledger row 321, walk prints ()")
    31	    assert(Tag[\(ZZ32, String, Boolean)\]().asString, "Tag[\\(ZZ32,String,Boolean)\\]", "tuple of three; ledger row 321")
    32	    assert(Tag[\() -> ZZ32\]().asString, "Tag[\\()->ZZ32\\]", "arrow of no arguments; ledger row 321")
    33	    assert("<" || Box(1) || ">", "<Box>", "concatenation goes through asString; ledger row 321")
    34	    assert(Nothing.asString, "Nothing", "prelude singleton Nothing; ledger row 321")
    35	    assert(None.asString, "None", "prelude singleton None; ledger row 321")
    36	    var caught: String = "nothing caught"
    37	    try
    38	        throw Boom
    39	    catch e
    40	        Boom => caught := "Boom caught"
    41	    end
    42	    assert(caught, "Boom caught", "a throw of an object with no asString reaches its handler; FException.java:22-23, ledger row 321")
    43	    println("PASS")
    44	  end
    45	
    46	end
    47	tests=DefaultRenderRungS
    48	link
    49	run
    50	run_out_contains=PASS
    51	run_out_does_not_contain=FAIL

